        "qid",
        "label",
        "poi_type",
        "distance_m",
        "n_departures",
        "n_routes",
        "accessibility_score",
    ],
    "outputs/t13_city_clusters.csv": ["city_id", "city_name", "year", "cluster_id"],
}

MIN_ROWS = {
    "outputs/t01_selected_indicators.csv": 1,
    "outputs/t05_clean_stops.csv": 1,
    "outputs/t08_pois_clean.csv": 1,
    "outputs/t10_accessibility_scores.csv": 1,
    "outputs/t13_city_clusters.csv": 1,
}


def _check_file(rel_path):
