            reader = csv.reader(fh)
            rows = list(reader)
    except Exception as exc:  # pragma: no cover - defensive
        return False, "could not parse {} ({})".format(rel_path, exc), None, None
    if not rows:
        return False, "file has no header row: {}".format(rel_path), None, None
    header = [c.strip() for c in rows[0]]
    return True, "", header, rows


def _check_exists(name, rel_path):
    ok, msg, _, _ = _check_file(rel_path)
    if ok:
        return name, True, "OK: {} exists and is non-empty.".format(rel_path)
    return name, False, "FAILED: {}".format(msg)


def _check_nonempty_rows(name, rel_path):
    ok, msg, header, rows = _check_file(rel_path)
    if not ok:
        return name, False, "FAILED: {}".format(msg)
    data_rows = len(rows) - 1
    min_rows = MIN_ROWS[rel_path]
    if data_rows < min_rows:
        return (
            name,
            False,
            "FAILED: {} has {} data row(s), expected at least {}.".format(
                rel_path, data_rows, min_rows
            ),
        )
    return (
        name,
        True,
        "OK: {} has {} data rows (min {} required).".format(
            rel_path, data_rows, min_rows
        ),
    )


def _check_header(name, rel_path):
    ok, msg, header, rows = _check_file(rel_path)
    if not ok:
        return name, False, "FAILED: {}".format(msg)
    expected = EXPECTED_COLUMNS[rel_path]
    if header != expected:
        return (
            name,
            False,
            "FAILED: {} header {} != expected {}.".format(rel_path, header, expected),
        )
    return name, True, "OK: {} header matches expected columns.".format(rel_path)


def _check_numeric_columns(name, rel_path, columns):
    ok, msg, header, rows = _check_file(rel_path)
    if not ok:
        return name, False, "FAILED: {}".format(msg)
    idx = {c: header.index(c) for c in columns if c in header}
    missing = [c for c in columns if c not in header]
    if missing:
        return name, False, "FAILED: {} missing columns {}.".format(rel_path, missing)
    bad = 0
    for row in rows[1:]:
        if not row:
            continue
        for col in idx:
            val = row[idx[col]].strip()
            try:
                float(val)
            except (ValueError, IndexError):
                bad += 1
    if bad:
        return (
            name,
            False,
            "FAILED: {} has {} non-numeric value(s) in numeric columns {}.".format(
                rel_path, bad, columns
            ),
        )
    return (
        name,
        True,
        "OK: numeric columns {} in {} are all numeric.".format(columns, rel_path),
    )


def _check_unique_keys(name, rel_path, key):
    ok, msg, header, rows = _check_file(rel_path)
    if not ok:
        return name, False, "FAILED: {}".format(msg)
    if key not in header:
        return name, False, "FAILED: {} missing key column '{}'.".format(rel_path, key)
