    seen = set()
    dupes = 0
    for row in rows[1:]:
        if not row:
            continue
        v = row[i].strip()
        if v in seen:
            dupes += 1
        else:
            seen.add(v)
    if dupes:
        return (
            name,
            False,
            "FAILED: {} has {} duplicate value(s) in '{}'.".format(rel_path, dupes, key),
        )
    return (
        name,
        True,
        "OK: '{}' values in {} are unique ({} rows).".format(key, rel_path, len(seen)),
    )


