    files = list(EXPECTED_COLUMNS)
    for rel in files:
        short = rel.split("/")[-1].replace(".csv", "")
        results.append(_check_exists("exists_" + short, rel))
        results.append(_check_nonempty_rows("nonempty_rows_" + short, rel))
        results.append(_check_header("header_" + short, rel))

    results.append(
        _check_numeric_columns(
            "numeric_latlon_t05",
            "outputs/t05_clean_stops.csv",
            ["stop_lat", "stop_lon"],
        )
    )
    results.append(
        _check_numeric_columns(
            "numeric_latlon_t08",
            "outputs/t08_pois_clean.csv",
            ["latitude", "longitude"],
        )
    )
    results.append(
        _check_numeric_columns(
            "numeric_scores_t10",
            "outputs/t10_accessibility_scores.csv",
            ["distance_m", "accessibility_score"],
        )
    )
    results.append(
        _check_numeric_columns(
            "numeric_cluster_id_t13",
            "outputs/t13_city_clusters.csv",
            ["year", "cluster_id"],
        )
    )
    results.append(_check_unique_keys("unique_stop_id_t05", "outputs/t05_clean_stops.csv", "stop_id"))
    results.append(_check_unique_keys("unique_qid_t08", "outputs/t08_pois_clean.csv", "qid"))
    results.append(_check_unique_keys("unique_qid_t10", "outputs/t10_accessibility_scores.csv", "qid"))

